(function(){if(typeof window!=="undefined"&&!window.__ecaph_reloading){window.__ecaph_reloading=true;try{var last=sessionStorage.getItem("ecaph_chunk_reload");if(!last||Date.now()-parseInt(last,10)>3000){sessionStorage.setItem("ecaph_chunk_reload",Date.now().toString());setTimeout(function(){window.location.reload();},100);}}catch(e){window.location.reload();}}})();